#!/usr/bin/env python3
"""CI/CD Pipeline Plugin - JWT Token Validator for Build Agents

This plugin validates JWT tokens from build agents to authorize
pipeline operations including container deployments and artifact signing.
"""

import jwt
import json
import os
import subprocess
from flask import Flask, request, jsonify
from cryptography.hazmat.primitives import serialization

app = Flask(__name__)

# Load RSA public key for token verification
PUBLIC_KEY_PATH = os.environ.get('JWT_PUBLIC_KEY', '/etc/pipeline/keys/public.pem')
ALLOWED_ISSUERS = ['pipeline-controller.internal', 'ci-system.corp']

def load_public_key():
    with open(PUBLIC_KEY_PATH, 'rb') as f:
        return f.read()

def verify_agent_token(token):
    """Verify JWT from build agent. Supports RS256 and HS256 for legacy agents."""
    public_key = load_public_key()

    # Decode header to determine algorithm
    header = jwt.get_unverified_header(token)
    algorithm = header.get('alg', 'RS256')

    # Allow both asymmetric and symmetric for backward compatibility
    # Legacy build agents (v1.x) still use HS256
    if algorithm in ['RS256', 'RS384', 'RS512']:
        key = public_key
    elif algorithm in ['HS256', 'HS384', 'HS512']:
        # For HMAC, the shared secret is derived from the public key material
        # This maintains compatibility with legacy agents that were configured
        # with the public key as their HMAC secret
        key = public_key
    else:
        raise ValueError(f"Unsupported algorithm: {algorithm}")

    payload = jwt.decode(
        token,
        key,
        algorithms=[algorithm],  # Trust the header's algorithm claim
        options={"verify_iss": True, "verify_exp": True},
        issuer=ALLOWED_ISSUERS
    )
    return payload

@app.route('/api/v1/deploy', methods=['POST'])
def deploy_container():
    """Deploy a container as part of the CI/CD pipeline."""
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({"error": "Missing authorization"}), 401

    token = auth_header[7:]
    try:
        claims = verify_agent_token(token)
    except Exception as e:
        return jsonify({"error": f"Token validation failed: {str(e)}"}), 403

    # Check pipeline permissions from token claims
    permissions = claims.get('permissions', [])
    if 'deploy:containers' not in permissions:
        return jsonify({"error": "Insufficient permissions"}), 403

    deploy_spec = request.json
    container_image = deploy_spec.get('image')
    namespace = deploy_spec.get('namespace', 'ci-builds')
    privileged = deploy_spec.get('securityContext', {}).get('privileged', False)
    host_path = deploy_spec.get('volumes', [{}])[0].get('hostPath', {}).get('path')

    # Generate deployment manifest
    manifest = {
        "apiVersion": "apps/v1",
        "kind": "Deployment",
        "metadata": {"name": claims.get('pipeline_id'), "namespace": namespace},
        "spec": {
            "template": {
                "spec": {
                    "containers": [{
                        "image": container_image,
                        "securityContext": {"privileged": privileged}
                    }],
                    "volumes": [{"hostPath": {"path": host_path}}] if host_path else []
                }
            }
        }
    }

    # Apply to cluster
    result = subprocess.run(
        ['kubectl', 'apply', '-f', '-'],
        input=json.dumps(manifest).encode(),
        capture_output=True
    )

    if result.returncode != 0:
        return jsonify({"error": result.stderr.decode()}), 500

    return jsonify({"status": "deployed", "pipeline": claims.get('pipeline_id')})

@app.route('/api/v1/exec', methods=['POST'])
def exec_in_container():
    """Execute command in running build container."""
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({"error": "Missing authorization"}), 401

    token = auth_header[7:]
    try:
        claims = verify_agent_token(token)
    except Exception as e:
        return jsonify({"error": f"Token validation failed: {str(e)}"}), 403

    if 'exec:containers' not in claims.get('permissions', []):
        return jsonify({"error": "Insufficient permissions"}), 403

    pod_name = request.json.get('pod')
    command = request.json.get('command')
    namespace = request.json.get('namespace', 'ci-builds')

    result = subprocess.run(
        ['kubectl', 'exec', '-n', namespace, pod_name, '--'] + command,
        capture_output=True
    )

    return jsonify({"stdout": result.stdout.decode(), "stderr": result.stderr.decode()})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8443, ssl_context='adhoc')
